def median(arr):
  arr.sort()
  if len(arr) % 2 != 0:
    median_index = int(len(arr) / 2)
    return arr[median_index]
  else:
    lower_index = int(len(arr) / 2) - 1
    upper_index = int(len(arr) / 2)
    return (arr[lower_index] + arr[upper_index]) / 2

def mode(arr):
  counts = {}
  for num in arr:
    if num in counts:
      counts[num] += 1
    else:
      counts[num] = 1

  max_frequency = 0
  max_value = None
  for num, frequency in counts.items():
    if frequency > max_frequency:
      max_frequency = frequency
      max_value = num

  return max_value

