def find_basket_combinations(items, basket_limit):
    list_of_combinations = []
    if len(items) == 0:
        return list_of_combinations

    items.sort()
    start_ind = 0
    backtrack(start_ind, items, basket_limit, list_of_combinations, [])
    return list_of_combinations

def backtrack(start_ind, items, basket_limit, list_of_combinations, curr_comb):
    if sum(curr_comb) > basket_limit:
        return
    if sum(curr_comb) <= basket_limit:
        list_of_combinations.append(curr_comb.copy())
    for i in range(start_ind, len(items)):
        curr_comb.append(items[i])
        backtrack(i+1, items, basket_limit, list_of_combinations, curr_comb)
        curr_comb.pop()

